use marketfeed_event_pulse::wire::Rfc3339Time;
use serde_json::Value;

// Captured from source82a871b BEFORE changing the backend. The fixture is not
// regenerated by this test; it also includes the old capture UTC conversion.
fn legacy_vectors() -> Value {
    serde_json::from_slice(include_bytes!(
        "../../../docs/evidence/timestamp-backend-20261020/compatibility-vectors.json"
    ))
    .unwrap()
}

#[test]
fn frozen_parser_and_utc_bytes_survive_backend_migration() {
    let vectors = legacy_vectors();
    let rows = vectors["parse"].as_array().unwrap();
    assert_eq!(rows.len(), 302);
    for row in rows {
        let input = row["input"].as_str().unwrap();
        let parsed = Rfc3339Time::parse(input);
        assert_eq!(
            parsed.is_ok(),
            row["accepted"].as_bool().unwrap(),
            "{input}"
        );
        if let Ok(parsed) = parsed {
            assert_eq!(
                parsed.canonical(),
                row["canonical"].as_str().unwrap(),
                "{input}"
            );
            assert_eq!(
                parsed.utc_micros(),
                row["utc_micros"].as_i64().unwrap(),
                "{input}"
            );
            assert_eq!(
                parsed.utc_canonical().ok().as_deref(),
                row["utc_canonical"].as_str(),
                "{input}"
            );
        }
    }
}

#[test]
fn negative_submicroseconds_and_i64_extrema_retain_floor_and_bytes() {
    let vectors = legacy_vectors();
    let rows = vectors["nanos"].as_array().unwrap();
    assert_eq!(rows.len(), 17);
    for row in rows {
        let input = row["input"].as_i64().unwrap();
        let parsed = Rfc3339Time::from_unix_nanos(input).unwrap();
        assert_eq!(
            parsed.canonical(),
            row["canonical"].as_str().unwrap(),
            "{input}"
        );
        assert_eq!(parsed.utc_micros(), input.div_euclid(1000));
        assert_eq!(parsed.utc_canonical().unwrap(), parsed.canonical());
    }
}

#[test]
fn full_microsecond_calendar_range_is_not_limited_by_nanoseconds() {
    let minimum = Rfc3339Time::parse("0000-01-01T00:00:00Z").unwrap();
    assert_eq!(minimum.utc_micros(), -62_167_219_200_000_000);
    assert_eq!(minimum.utc_canonical().unwrap(), "0000-01-01T00:00:00Z");
    let maximum = Rfc3339Time::parse("9999-12-31T23:59:59.999999Z").unwrap();
    assert_eq!(maximum.utc_micros(), 253_402_300_799_999_999);
    assert_eq!(
        maximum.utc_canonical().unwrap(),
        "9999-12-31T23:59:59.999999Z"
    );
    for input in ["0000-01-01T00:00:00+23:59", "9999-12-31T23:59:59-23:59"] {
        assert!(Rfc3339Time::parse(input).unwrap().utc_canonical().is_err());
    }
}

#[test]
fn proleptic_gregorian_centuries_keep_the_four_hundred_year_rule() {
    for year in [0, 1600, 2000, 2400] {
        let input = format!("{year:04}-02-29T00:00:00Z");
        assert_eq!(
            Rfc3339Time::parse(&input).unwrap().utc_canonical().unwrap(),
            input
        );
    }
    for year in [100, 1700, 1800, 1900, 2100] {
        assert!(Rfc3339Time::parse(&format!("{year:04}-02-29T00:00:00Z")).is_err());
    }
}
